# define schema for what the pandas udf will return
product_schema = [StructField(p, IntegerType()) for p in product]
schema = StructType([StructField('partition_date', StringType())] +
                    product_schema +
                    [StructField('cif_number', StringType())])

def get_transformed_data(df, product):
    # result inisialization
    result = pd.DataFrame()
    first_open = df['account_open_date'].unique().tolist()[0]
    result['partition_date'] = [first_open]
    for p in product:
        result[p] = 0

    close_dates = []
    open_dates = df['account_open_date'].unique().tolist()
    while (len(open_dates) != 0) or (len(close_dates) != 0):
        try:
            close_date = min(close_dates)

            last_close = result.loc[result['partition_date'] <= close_date, ]
            last_close = last_close.tail(1)
            last_close['partition_date'] = close_date

            close_account = df.loc[df['account_close_date'] == close_date, ]
            close_product = close_account['biu'].to_list()
            c = Counter(close_product)

            if (open_date > close_date) or ((open_date < close_date) & (len(open_dates) == 0)):
                for k in c.keys():
                    x = last_close.loc[last_close['partition_date'] == close_date, k]
                    last_close.loc[last_close['partition_date'] == close_date, k] = x - c[k]
                result = result.append(last_close)
                result = result.sort_values("partition_date")
                close_dates.remove(close_date)
            elif close_date == open_date:
                for k in c.keys():
                    x = last_close.loc[last_close['partition_date'] == close_date, k]
                    result.loc[result['partition_date'] == close_date, k] = x - c[k]
                close_dates.remove(close_date)
        except:
            pass

        try:
            open_date = min(open_dates)

            last_open = result.loc[result['partition_date'] <= open_date, ]
            last_open = last_open.tail(1)
            last_open['partition_date'] = open_date

            open_account = df.loc[df['account_open_date'] == open_date, ]
            close_date = [x for x in open_account.account_close_date.unique().tolist() if x not in [None, np.nan]]
            if len(close_date) > 0:
                close_dates = set(close_dates + close_date)
                close_dates = list(close_dates)

            open_product = open_account['biu'].to_list()
            c = Counter(open_product)
            for k in c.keys():
                x = last_open.loc[last_open['partition_date'] == open_date, k].to_list()[0]
                last_open.loc[last_open['partition_date'] == open_date, k] = x + c[k]

            result = result.append(last_open)
            open_dates.remove(open_date)
        except:
            pass

    result.reset_index(drop=True, inplace=True)
    result.drop(0, inplace=True)
    result.reset_index(drop=True, inplace=True)
    return result

@pandas_udf(schema, functionType=PandasUDFType.GROUPED_MAP)
def transform_data(df):

    df.loc[df['account_open_date'] == 'NULL', 'account_open_date'] = None
    df.loc[df['account_close_date'] == 'NULL', 'account_close_date'] = None
    df = df.sort_values('account_open_date')
    # get cif number
    cif_number = df['cif_number'].tolist()[0]
    result = get_transformed_data(df, product)
    result['cif_number'] = cif_number

    return result

dataset = df.groupBy('cif_number').apply(transform_data)
dataset = dataset.withColumn('training_date', F.lit(today.strftime('%Y-%m-%d')))

